"""Controller-selectable local automation editor, via existing pinned lab API."""
from ui_layout import apply
PAGE=r'''<!DOCTYPE html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Automatik</title>
<style>body{margin:0}label{display:flex;flex-direction:column;gap:4px}input,select,button{font:inherit;padding:8px;border:1px solid var(--border);border-radius:8px;color:inherit;background:var(--card);min-width:0}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}.actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.check{flex-direction:row;align-items:center}.muted{color:var(--muted)}.rule{border-top:1px solid var(--border);padding:12px 0}.rule h3{margin:0 0 6px}fieldset{border:1px solid var(--border);border-radius:8px;margin:14px 0;padding:12px}legend{font-weight:bold}.days{display:flex;flex-wrap:wrap;gap:12px}.primary{background:var(--accent);color:white}</style>
</head><body><main><h1>Automatik</h1><p>Lokal lysstyring</p><nav></nav>
<section class="card"><div class="fields"><label>Controller<select id="ctl"></select></label></div><p id="state" role="status">Indlæser…</p><div class="actions"><button id="refresh">Opdater</button><button id="new" class="primary">Ny zone</button></div><div id="rules"></div></section>
<section class="card" id="editor" hidden><h2 id="editorTitle">Ny zone</h2><form id="form">
<div class="fields"><label>Zonenavn<input id="name" maxlength="80" required></label><label>DALI-bus<select id="bus"><option>1</option><option>2</option><option>3</option></select></label><label>Destinationstype<select id="kind"><option value="gear">Armatur</option><option value="group">Gruppe</option></select></label><label>Destination<select id="target" required></select></label><label>Normalniveau (0–254)<input id="day_level" type="number" min="0" max="254" value="180" required></label><label>Overstyring efter manuel kommando (sek.)<input id="override_seconds" type="number" min="0" max="86400" value="1800" required></label></div>
<fieldset><legend>Tidsprogram og natsænkning</legend><label class="check"><input id="schedule" type="checkbox"> Anvend ugeprogram</label><div class="days" id="days"></div><div class="fields"><label>Fra<input id="start" type="time" value="07:00" required></label><label>Til<input id="end" type="time" value="16:00" required></label><label>Tidszone<input id="timezone" value="Europe/Copenhagen" maxlength="64" required></label><label>Niveau udenfor tidsprogram<input id="night_level" type="number" min="0" max="254" value="0" required></label></div></fieldset>
<fieldset><legend>Bevægelse / tilstedeværelse</legend><div class="fields"><label>Sensor<select id="occupancy"></select></label><label>Efterløb (sek.)<input id="hold" type="number" min="5" max="86400" value="900" required></label><label>Niveau ved fravær<input id="vacancy_level" type="number" min="0" max="254" value="0" required></label></div></fieldset>
<fieldset><legend>Dagslysregulering</legend><div class="fields"><label>Lyssensor<select id="daylight"></select></label><label>Relativt setpunkt (1–254)<input id="setpoint" type="number" min="1" max="254" value="128" required></label><label>Dødbånd<input id="deadband" type="number" min="1" max="100" value="8" required></label><label>Min. niveau<input id="min_level" type="number" min="1" max="254" value="20" required></label><label>Maks. niveau<input id="max_level" type="number" min="1" max="254" value="254" required></label><label>Reguleringstrin<input id="step" type="number" min="1" max="30" value="5" required></label></div><p class="muted">Relativ sensorværdi, ikke kalibreret lux. Indregulér på testinstallation.</p></fieldset>
<fieldset><legend>Sensorfejl</legend><div class="fields"><label>Gyldighed af seneste måling (sek.)<input id="sensor_timeout" type="number" min="10" max="3600" value="120" required></label><label>Fallback<select id="fallback"><option value="hold">Behold lysniveau</option><option value="level">Brug fast niveau</option></select></label><label>Fallback-niveau<input id="fallback_level" type="number" min="0" max="254" value="180" required></label></div></fieldset>
<label class="check"><input type="checkbox" id="enabled"> Aktivér zonen ved gem</label><label class="check"><input type="checkbox" id="confirm"> Bekræft at destination og sensorer er kontrolleret</label><div class="actions"><button class="primary" type="submit">Gem zone</button><button id="cancel" type="button">Annuller</button></div></form></section>
<script>
const $=id=>document.getElementById(id);let controllers=[],snapshot=null,editing=null,busy=false;
const nums=["day_level","night_level","vacancy_level","override_seconds","hold","setpoint","deadband","min_level","max_level","step","sensor_timeout","fallback_level"];
const texts=["name","timezone","fallback"];
function opt(e,v,t){e.add(new Option(t,String(v)));}
function status(t){$("state").textContent=t;}
async function req(path,d){const base=location.pathname.replace(/\/automation\/?$/,"/").replace(/[^/]*$/,"");const r=await fetch(base+path,{method:d===undefined?"GET":"POST",headers:{"Content-Type":"application/json"},body:d===undefined?undefined:JSON.stringify(d),cache:"no-store"});const j=await r.json();if(!r.ok||j.ok===false)throw Error(j.error||"HTTP "+r.status);return j;}
function selected(){return controllers.find(c=>c.id===$("ctl").value);}
async function call(action,data={}){const c=selected();if(!c||!snapshot)throw Error("Vælg controller");const id=snapshot.controller_id;const d={...data,mode:"automation",action,controller_id:id};const j=c.id==="local"?await req("api/lab/run",d):await req("api/lab/remote",{registry_id:c.id,controller_id:id,operation:"run",test:d});if(j.controller_id!==id)throw Error("Controller-ID ændret");return j;}
function lock(v){busy=v;$("ctl").disabled=v;$("refresh").disabled=v;$("new").disabled=v||!snapshot?.automation_enabled;for(const e of $("rules").querySelectorAll("button"))e.disabled=v;for(const e of $("form").querySelectorAll("button,input,select"))e.disabled=v;}
function button(parent,label,fn){const b=document.createElement("button");b.type="button";b.textContent=label;b.onclick=fn;parent.append(b);}
async function change(action,data){if(busy)return;lock(true);try{const j=await call(action,{...data,confirm:true});snapshot.automation_rules=j.automation_rules;render();status("Ændring gemt.");}catch(e){status(String(e));}finally{lock(false);}}
function render(){const root=$("rules");root.replaceChildren();if(!snapshot)return;for(const r of snapshot.automation_rules||[]){const box=document.createElement("div");box.className="rule";const h=document.createElement("h3");h.textContent=r.name+" · DALI "+r.bus;const p=document.createElement("p");p.textContent=(r.enabled?"Aktiv":"Deaktiveret")+" · "+(r.runtime?.status||"ukendt")+" · Pause "+(r.runtime?.override_remaining||0)+" s";const row=document.createElement("div");row.className="actions";button(row,"Rediger",()=>edit(r));button(row,r.enabled?"Deaktivér":"Aktivér",()=>change("automation_enable",{id:r.id,enabled:!r.enabled}));button(row,"Pause 30 min.",()=>change("automation_override",{id:r.id,seconds:1800}));button(row,"Genoptag",()=>change("automation_override",{id:r.id,seconds:0}));button(row,"Fjern",()=>{if(confirm("Fjern zonen? Lysniveauet ændres ikke direkte."))change("automation_remove",{id:r.id});});box.append(h,p,row);root.append(box);}if(!root.children.length)root.textContent="Ingen zoner konfigureret.";}
function choices(){const b=Number($("bus").value),kind=$("kind").value;const dest=$("target");dest.replaceChildren();opt(dest,"","Vælg destination");if(kind==="gear"){for(const g of snapshot?.gear||[])if(g.bus===b&&g.online&&!g.address_conflict&&g.ha_uid)opt(dest,g.ha_uid,g.name||"Armatur "+g.address);}else for(const g of snapshot?.groups||[])if(g.bus===b)opt(dest,g.group,"Gruppe "+g.group);for(const [id,t] of [["occupancy",3],["daylight",4]]){const el=$(id);el.replaceChildren();opt(el,"","Ingen");for(const i of snapshot?.input_instances||[])if(i.bus===b&&i.instance_type===t&&i.enabled)opt(el,i.address+":"+i.instance,"Adresse "+i.address+" / instance "+i.instance);}}
const hm=n=>String(Math.floor(n/60)).padStart(2,"0")+":"+String(n%60).padStart(2,"0");
function edit(r){if(busy||!snapshot?.automation_enabled)return;editing=r?.id||null;$("form").reset();$("editor").hidden=false;$("editorTitle").textContent=r?"Redigér zone":"Ny zone";if(r){$("bus").value=r.bus;$("kind").value=r.target_kind;for(const k of [...nums,...texts])$(k).value=r[k];$("schedule").checked=r.schedule;$("enabled").checked=r.enabled;$("start").value=hm(r.start);$("end").value=hm(r.end);}for(const e of $("days").querySelectorAll("input"))e.checked=!r||r.days.includes(Number(e.value));choices();if(r){$("target").value=String(r.target);for(const k of ["occupancy","daylight"])if(r[k])$(k).value=r[k].address+":"+r[k].instance;}$("confirm").checked=false;}
async function load(){if(busy)return;lock(true);snapshot=null;$("editor").hidden=true;try{const c=selected();if(!c)throw Error("Ingen controller");const id=c.remote_controller_id||c.controller_id;const j=c.id==="local"?await req("api/devices"):await req("api/lab/remote",{registry_id:c.id,controller_id:id,operation:"snapshot"});if(j.controller_id!==id)throw Error("Controller-ID ændret");snapshot=j;render();status(j.automation_enabled?"Lokal automatik tilgængelig":"Aktivér local_automation_enabled på hardware-controlleren og genstart.");}catch(e){$("rules").replaceChildren();status(String(e));}finally{lock(false);}}
function sensor(id){const v=$(id).value;if(!v)return null;const [address,instance]=v.split(":").map(Number);return {address,instance};}
$("form").onsubmit=async e=>{e.preventDefault();if(busy||!snapshot)return;if(!$("confirm").checked){status("Bekræft konfigurationen.");return;}const kind=$("kind").value,d={id:editing,bus:Number($("bus").value),target_kind:kind,target:kind==="group"?Number($("target").value):$("target").value,enabled:$("enabled").checked,schedule:$("schedule").checked,start:$("start").value,end:$("end").value,days:[...$("days").querySelectorAll("input:checked")].map(x=>Number(x.value)),occupancy:sensor("occupancy"),daylight:sensor("daylight"),confirm:true};for(const k of nums)d[k]=Number($(k).value);for(const k of texts)d[k]=$(k).value;lock(true);try{const j=await call("automation_save",d);snapshot.automation_rules=j.automation_rules;$("editor").hidden=true;render();status("Zone gemt.");}catch(err){status(String(err));}finally{lock(false);}};
["Man","Tir","Ons","Tor","Fre","Lør","Søn"].forEach((day,i)=>{const l=document.createElement("label");l.className="check";const e=document.createElement("input");e.type="checkbox";e.value=i;e.checked=true;l.append(e,document.createTextNode(day));$("days").append(l);});
$("bus").onchange=choices;$("kind").onchange=choices;$("new").onclick=()=>edit(null);$("cancel").onclick=()=>{$("editor").hidden=true;};$("refresh").onclick=load;$("ctl").onchange=()=>{localStorage.setItem("pulsar_active_controller",$("ctl").value);load();};
(async()=>{try{const j=await req("api/controllers");controllers=[j.local,...j.controllers].filter(Boolean);for(const c of controllers)opt($("ctl"),c.id,c.name||c.id);const stored=localStorage.getItem("pulsar_active_controller");if(controllers.some(c=>c.id===stored))$("ctl").value=stored;await load();}catch(e){status(String(e));}})();
</script></main></body></html>'''
def page():return apply(PAGE,"automation")
